package com.fifotech.task.service;
import com.fifotech.task.domain.*;import com.fifotech.task.dto.ApiDtos.*;import com.fifotech.task.exception.ApiException;import com.fifotech.task.repository.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional public class TaskService {
 private final TaskRepository tasks;private final UserRepository users;public TaskService(TaskRepository tasks,UserRepository users){this.tasks=tasks;this.users=users;}
 public TaskResponse create(TaskRequest r,User actor){User assignee=employee(r.assignedToId());checkCanAssign(actor,assignee);return view(tasks.save(new TaskItem(r.title().trim(),r.description(),r.priority(),r.deadline(),assignee,actor)));}
 @Transactional(readOnly=true) public List<TaskResponse> list(User actor,TaskStatus status,Priority priority,Long assignee){Long employee=actor.getRole()==Role.EMPLOYEE?actor.getId():null;Long manager=actor.getRole()==Role.MANAGER?actor.getId():null;return tasks.search(status,priority,assignee,employee,manager).stream().map(this::view).toList();}
 @Transactional(readOnly=true) public TaskResponse get(Long id,User actor){TaskItem t=find(id);checkCanView(actor,t);return view(t);}
 public TaskResponse update(Long id,TaskRequest r,User actor){TaskItem t=find(id);checkCanManage(actor,t);User assignee=employee(r.assignedToId());checkCanAssign(actor,assignee);t.setTitle(r.title().trim());t.setDescription(r.description());t.setPriority(r.priority());t.setDeadline(r.deadline());t.setAssignedTo(assignee);return view(tasks.save(t));}
 public TaskResponse updateStatus(Long id,TaskStatus status,User actor){TaskItem t=find(id);if(actor.getRole()!=Role.EMPLOYEE||!t.getAssignedTo().getId().equals(actor.getId()))throw new ApiException(HttpStatus.FORBIDDEN,"Employees can update only their own tasks");if(t.getStatus()==TaskStatus.DONE&&status!=TaskStatus.DONE)throw new ApiException(HttpStatus.CONFLICT,"Completed tasks cannot be reopened");if(status.ordinal()<t.getStatus().ordinal())throw new ApiException(HttpStatus.CONFLICT,"Task status cannot move backwards");t.setStatus(status);return view(tasks.save(t));}
 public void delete(Long id){tasks.delete(find(id));}
 @Transactional(readOnly=true) public List<TaskResponse> report(User actor){return list(actor,null,null,null);}
 private User employee(Long id){User u=users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Assignee not found"));if(u.getRole()!=Role.EMPLOYEE||!u.isActive())throw new ApiException(HttpStatus.BAD_REQUEST,"Tasks can only be assigned to active employees");return u;}
 private void checkCanAssign(User actor,User assignee){if(actor.getRole()==Role.MANAGER&&(assignee.getManager()==null||!assignee.getManager().getId().equals(actor.getId())))throw new ApiException(HttpStatus.FORBIDDEN,"Managers can assign tasks only to employees in their team");}
 private void checkCanView(User a,TaskItem t){if(a.getRole()==Role.ADMIN)return;if(a.getRole()==Role.EMPLOYEE&&t.getAssignedTo().getId().equals(a.getId()))return;if(a.getRole()==Role.MANAGER&&t.getAssignedBy().getId().equals(a.getId())&&t.getAssignedTo().getManager()!=null&&t.getAssignedTo().getManager().getId().equals(a.getId()))return;throw new ApiException(HttpStatus.FORBIDDEN,"You cannot access this task");}
 private void checkCanManage(User a,TaskItem t){if(a.getRole()==Role.ADMIN)return;if(a.getRole()==Role.MANAGER){checkCanView(a,t);return;}throw new ApiException(HttpStatus.FORBIDDEN,"You cannot manage this task");}
 private TaskItem find(Long id){return tasks.findDetailedById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Task not found"));}
 private TaskResponse view(TaskItem t){return new TaskResponse(t.getId(),t.getTitle(),t.getDescription(),t.getStatus(),t.getPriority(),t.getDeadline(),t.getAssignedTo().getId(),t.getAssignedTo().getFullName(),t.getAssignedBy().getId(),t.getAssignedBy().getFullName(),t.getCreatedAt(),t.getUpdatedAt());}
}
